/**
 * Builtin Paperclip control-plane tools for the Groq adapter.
 *
 * The Paperclip server does not (yet) pass a `ctx.tools` surface to external
 * adapters, so chat-only models cannot act on issues — they narrate work that
 * never happens and runs end in "missing disposition". This module gives the
 * model a minimal HTTP tool surface against the local control plane.
 *
 * Auth: deployment mode local_trusted needs no token; when ctx.authToken is
 * present it is sent as a Bearer header for actor attribution.
 */
function apiBaseUrl() {
    const host = (process.env.PAPERCLIP_LISTEN_HOST ?? "localhost").trim() || "localhost";
    const port = process.env.PAPERCLIP_LISTEN_PORT ?? process.env.PORT ?? "3100";
    return (process.env.PAPERCLIP_RUNTIME_API_URL ??
        process.env.PAPERCLIP_API_URL ??
        `http://${host === "0.0.0.0" || host === "::" ? "localhost" : host}:${port}`);
}
export function buildPaperclipTools(ctx) {
    const agent = ctx.agent;
    const authToken = typeof ctx.authToken === "string" ? ctx.authToken : null;
    const base = apiBaseUrl();
    const call = async (method, path, body) => {
        const headers = { "content-type": "application/json" };
        if (authToken)
            headers.authorization = "Bearer " + authToken;
        const res = await fetch(base + path, {
            method,
            headers,
            body: body === undefined ? undefined : JSON.stringify(body),
        });
        const text = await res.text();
        let json;
        try {
            json = JSON.parse(text);
        }
        catch {
            json = text;
        }
        if (!res.ok) {
            return { ok: false, status: res.status, error: json };
        }
        return { ok: true, status: res.status, result: json };
    };
    const trimIssue = (i) => ({
        id: i.id,
        identifier: i.identifier,
        title: i.title,
        status: i.status,
        priority: i.priority,
        assigneeAgentId: i.assigneeAgentId ?? i.assigneeId ?? null,
        parentId: i.parentId ?? null,
    });
    const tools = [
        {
            name: "paperclip_list_issues",
            description: "List issues in this company. Optionally filter by status (backlog, todo, in_progress, in_review, done, blocked, cancelled) or assigneeAgentId.",
            parameters: {
                type: "object",
                properties: {
                    status: { type: "string" },
                    assigneeAgentId: { type: "string" },
                },
            },
            run: async (args) => {
                const r = await call("GET", `/api/companies/${agent.companyId}/issues`);
                if (!r.ok)
                    return r;
                let items = Array.isArray(r.result) ? r.result : [];
                if (args.status)
                    items = items.filter((i) => i.status === args.status);
                if (args.assigneeAgentId)
                    items = items.filter((i) => (i.assigneeAgentId ?? i.assigneeId) === args.assigneeAgentId);
                return { ok: true, issues: items.map(trimIssue) };
            },
        },
        {
            name: "paperclip_get_issue",
            description: "Fetch one issue by its UUID id.",
            parameters: {
                type: "object",
                properties: { issueId: { type: "string" } },
                required: ["issueId"],
            },
            run: async (args) => {
                const r = await call("GET", `/api/issues/${args.issueId}`);
                if (!r.ok)
                    return r;
                return { ok: true, issue: trimIssue(r.result), description: r.result.description ?? null };
            },
        },
        {
            name: "paperclip_create_issue",
            description: "Create a new issue (task) in this company. Use parentIssueId to create a sub-task of an existing issue. Returns the created issue with its id and identifier.",
            parameters: {
                type: "object",
                properties: {
                    title: { type: "string" },
                    description: { type: "string" },
                    parentIssueId: { type: "string", description: "UUID of parent issue (optional)" },
                    assigneeAgentId: { type: "string", description: "UUID of agent to assign (optional)" },
                    status: { type: "string", description: "Initial status, default todo" },
                },
                required: ["title"],
            },
            run: async (args) => {
                const body = {
                    title: args.title,
                    description: args.description ?? "",
                    status: args.status ?? "todo",
                };
                if (args.assigneeAgentId)
                    body.assigneeAgentId = args.assigneeAgentId;
                let r;
                if (args.parentIssueId) {
                    r = await call("POST", `/api/issues/${args.parentIssueId}/children`, body);
                }
                else {
                    r = await call("POST", `/api/companies/${agent.companyId}/issues`, body);
                }
                if (!r.ok)
                    return r;
                const issue = r.result.issue ?? r.result;
                return { ok: true, issue: trimIssue(issue) };
            },
        },
        {
            name: "paperclip_update_issue_status",
            description: "Update an issue's status. Valid statuses: backlog, todo, in_progress, in_review, done, blocked, cancelled. Use this to record your disposition (e.g. in_review when delegating, done when finished).",
            parameters: {
                type: "object",
                properties: {
                    issueId: { type: "string" },
                    status: { type: "string" },
                },
                required: ["issueId", "status"],
            },
            run: async (args) => {
                const r = await call("PATCH", `/api/issues/${args.issueId}`, { status: args.status });
                if (!r.ok)
                    return r;
                return { ok: true, issue: trimIssue(r.result) };
            },
        },
        {
            name: "paperclip_assign_issue",
            description: "Assign an issue to an agent by agent UUID.",
            parameters: {
                type: "object",
                properties: {
                    issueId: { type: "string" },
                    assigneeAgentId: { type: "string" },
                },
                required: ["issueId", "assigneeAgentId"],
            },
            run: async (args) => {
                const r = await call("PATCH", `/api/issues/${args.issueId}`, { assigneeAgentId: args.assigneeAgentId });
                if (!r.ok)
                    return r;
                return { ok: true, issue: trimIssue(r.result) };
            },
        },
        {
            name: "paperclip_add_comment",
            description: "Add a comment to an issue (visible to all agents and the board).",
            parameters: {
                type: "object",
                properties: {
                    issueId: { type: "string" },
                    body: { type: "string" },
                },
                required: ["issueId", "body"],
            },
            run: async (args) => {
                const r = await call("POST", `/api/issues/${args.issueId}/comments`, { body: args.body });
                if (!r.ok)
                    return r;
                return { ok: true, commentId: r.result.id ?? null };
            },
        },
        {
            name: "paperclip_list_agents",
            description: "List agents in this company with their ids, names, and roles. Use the returned UUIDs for assignment.",
            parameters: { type: "object", properties: {} },
            run: async () => {
                const r = await call("GET", `/api/companies/${agent.companyId}/agents`);
                if (!r.ok)
                    return r;
                const items = Array.isArray(r.result) ? r.result : [];
                return {
                    ok: true,
                    agents: items.map((a) => ({
                        id: a.id,
                        name: a.name,
                        role: a.role,
                        title: a.title ?? null,
                        status: a.status,
                    })),
                };
            },
        },
    ];
    const byName = new Map(tools.map((t) => [t.name, t]));
    return {
        rawTools: tools.map((t) => ({
            name: t.name,
            description: t.description,
            parameters: t.parameters,
        })),
        invoke: async (name, args) => {
            const tool = byName.get(name);
            if (!tool)
                return { ok: false, error: `Unknown tool: ${name}` };
            try {
                return await tool.run(args ?? {});
            }
            catch (err) {
                return { ok: false, error: String(err?.message ?? err) };
            }
        },
    };
}
